/**
 * Compact feature types and constants
 */

import type { Message, UserMessage } from '../types.js';

/**
 * Compaction result returned after successful compaction
 */
export interface CompactionResult {
  /** Compact boundary marker message */
  boundaryMarker: {
    type: 'system'
    subtype: 'compact_boundary'
    content: string
    uuid: string
    timestamp: number
    compactMetadata: {
      trigger: 'auto' | 'manual'
      preCompactTokenCount: number
      postCompactTokenCount: number
      timestamp: number
    }
  }
  /** Summary messages generated by compaction */
  summaryMessages: UserMessage[]
  /** Messages to keep after compaction (recent important messages) */
  messagesToKeep?: Message[]
}

/**
 * Auto-compact configuration
 */
export interface AutoCompactConfig {
  /** Buffer tokens reserved for response (13,000 default) */
  bufferTokens: number
  /** Whether auto-compact is enabled */
  enabled: boolean
  /** Max consecutive failures before circuit breaker */
  maxConsecutiveFailures: number
}

/**
 * Auto-compact state tracking
 */
export interface AutoCompactTrackingState {
  /** Number of consecutive compaction failures */
  consecutiveFailures: number
  /** Whether last compaction was successful */
  compacted: boolean
  /** Turn ID for tracking */
  turnId: string
  /** Turn counter */
  turnCounter: number
}

/**
 * Compact thresholds
 */
export const COMPACT_THRESHOLDS = {
  /** 自动压缩预留缓冲上限（token） */
  AUTOCOMPACT_MAX_BUFFER: 50_000,
  /** 自动压缩预留缓冲比例（相对 maxOutputTokens） */
  AUTOCOMPACT_OUTPUT_BUFFER_RATIO: 0.3,
  /**
   * 预留输出缓冲（保留常量以兼容旧配置）。
   * 自动压缩阈值现在按 `contextWindow - min(50K, 0.3 * maxOutputTokens)` 计算。
   */
  AUTOCOMPACT_BUFFER: 12_000,
  /** Buffer tokens for warning threshold (~90%) */
  WARNING_BUFFER: 20_000,
  /** Max tokens to keep in session memory compaction */
  SESSION_MEMORY_MAX_TOKENS: 40_000,
  /** Min tokens to keep in session memory compaction */
  SESSION_MEMORY_MIN_TOKENS: 10_000,
  /** Min text blocks to always keep */
  SESSION_MEMORY_MIN_TEXT_BLOCKS: 5,
  /** Circuit breaker - max consecutive failures */
  MAX_CONSECUTIVE_FAILURES: 3,
} as const;

/**
 * 计算自动压缩阈值（可用输入上限）：
 *   contextWindow - min(50K, 0.3 * maxOutputTokens)
 *
 * 为输出预留的缓冲最多 50K，且不超过输出上限的 30%；
 * 剩余部分即为可安全发送的输入上限。
 *
 * 前端进度条与本函数共用同一套规则，保证 UI 与触发条件一致。
 */
export function getAutoCompactThreshold(contextWindow: number, maxOutputTokens: number): number {
  const output = Math.max(0, maxOutputTokens);
  const buffer = Math.min(
    COMPACT_THRESHOLDS.AUTOCOMPACT_MAX_BUFFER,
    COMPACT_THRESHOLDS.AUTOCOMPACT_OUTPUT_BUFFER_RATIO * output,
  );
  return Math.max(0, contextWindow - buffer);
}

/**
 * System prompt used for compact/summary LLM calls
 */
export const COMPACT_SYSTEM_PROMPT = '你是一个专业的对话摘要助手。请简洁准确地总结对话内容。';

/**
 * Default auto-compact config
 */
export const DEFAULT_AUTO_COMPACT_CONFIG: AutoCompactConfig = {
  bufferTokens: COMPACT_THRESHOLDS.AUTOCOMPACT_BUFFER,
  enabled: true,
  maxConsecutiveFailures: COMPACT_THRESHOLDS.MAX_CONSECUTIVE_FAILURES,
};